INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Dublin Theatre Festival is ‘All In’ for universal access', 'theatre-fest-aiming-to-reach-all-dubs', '<p>Now is a good time for community groups to start planning ahead for the autumn, and any community group in the wider Dublin area should consider attending the Dublin Theatre Festival (DTF) as it aims to be super-inclusive and participatory.</p>
<p>10% of tickets for selected festival productions will be made available for €10 to under 30s, unwaged, freelance artists and arts workers. Last year, 596 people registered for &#8217;10 for 10’ tickets. This year’s festival runs from Sept 28 &#8211; October 15.</p>
<p>Meanwhile, the festival’s Access Programme aims to boost participation and access and, last year, 18 assisted performances were programmed in the festival.</p>
<figure aria-describedby="caption-attachment-253230"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2023/07/7422E4F2-A5E2-4BF4-9DFD-496044D36632-390x400-1.jpg" alt="Sharon White, audience development and sales manager, Dublin Theatre Festival" width="390" height="400" srcset="https://changingireland.ie/wp-content/uploads/2023/07/7422E4F2-A5E2-4BF4-9DFD-496044D36632-390x400-1.jpg 390w, https://changingireland.ie/wp-content/uploads/2023/07/7422E4F2-A5E2-4BF4-9DFD-496044D36632-390x400-1-293x300.jpg 293w, https://changingireland.ie/wp-content/uploads/2023/07/7422E4F2-A5E2-4BF4-9DFD-496044D36632-390x400-1-24x24.jpg 24w, https://changingireland.ie/wp-content/uploads/2023/07/7422E4F2-A5E2-4BF4-9DFD-496044D36632-390x400-1-48x48.jpg 48w" sizes="(max-width: 390px) 100vw, 390px" /><figcaption><em>&#8211; Sharon White, audience development and sales manager, Dublin Theatre Festival</em></figcaption></figure>
<p><strong>All In Access</strong></p>
<p>As Sharon White of DTF says, “We recognise that there are barriers to attending the festival and the All In Access Programme aims to eliminate obstacles, and promotes and creates inclusion in the festival.</p>
<p>“We provide ISL interpreted, captioned, audio described, and relaxed performances for a range of shows in the festival,” she said.</p>
<p>To encourage wide society participation DTF offers:<br />
• Assisted performances for audiences with some types of sensory disabilities or impairments.<br />
• Free companion seats for individuals who need company or assistance to attend a show.<br />
• Access passes which are designed to simplify the booking process. This allows people to book wheelchair spaces and reserved seating in advance. If you or your group registers for access passes, you receive automatic discounts and, if helpful, complimentary companion tickets.<br />
• Access guides provide full venue and location details.</p>
<p>DTF will also try to provide additional services (eg transport) in response to individual needs.</p>
<p>The festival programme will be published at the end of July and registration opens for the various initiatives around that time, or make an early enquiry with DTF now (details below).</p>
<p>The assisted performances are programmed in conjunction with DTF’s venue partners and, says White, “Early registration enables us to identify other services or opportunities to develop the programme.”</p>
<p><strong>All In Ticket Initiative</strong></p>
<p>DTF is also seeking expressions of interest for participation in its All In Ticket Initiative, a scheme that provides groups and individuals with access to the festival with significantly discounted and complementary tickets.</p>
<p>The All In Ticket Initiative is available (but not limited) to the following organisations:<br />
• People with disabilities / groups or individuals and their carers.<br />
• Welfare groups.<br />
• Immigrant, integration and refugee associations.<br />
• Community groups</p>
<p><strong><em>For more information, email: access@dublintheatrefestival.ie</em></strong><br />
<strong><em>T: 01 677 8439.</em></strong></p>', '– Access Programme makes attending easy – 600 people bought discounted €10 tickets in 2022', 'https://changingireland.ie/wp-content/uploads/2023/07/governance-1.jpg', '', '[{"slug":"events","title":"Events"}]', '[{"slug":"access","title":"access"},{"slug":"access-programme","title":"access programme"},{"slug":"community","title":"Community"},{"slug":"community-groups","title":"community groups"},{"slug":"disability","title":"Disability"},{"slug":"dublin","title":"Dublin"},{"slug":"dublin-theatre-festival","title":"Dublin Theatre Festival"},{"slug":"festival","title":"Festival"},{"slug":"inclusion","title":"Inclusion"},{"slug":"integration","title":"integration"},{"slug":"migrant-groups","title":"migrant groups"},{"slug":"refugees","title":"refugees"},{"slug":"theatre","title":"theatre"}]', '', 253217, 1, '2023-07-19T11:21:24Z', '2023-07-19T11:20:31Z', '2023-07-19T11:21:24Z')
