INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('New strategy to place libraries at the heart of the community', 'new-strategy-to-place-libraries-at-the-heart-of-the-community', '<p>The strategy contains a 66-point action plan that, according to the Department of Rural and Community Development, aims to “develop every library in the country into a multi-purpose education and social space for all members of the community”.</p>
<p>The strategy also aims to treble the number of ‘My Open Library’ facilities to more than 90. These facilities provide library access 365 days a year from 8am-10pm to registered users.</p>
<p>Increased funding for books and additional Outreach Library Services and mobile libraries are other points included in the action plan.</p>
<p>The strategy also aims to increase the number and range of activities taking place in libraries, such as computer and language classes, cultural events and exhibitions.</p>
<p>Other commitments contained in ‘The Library is the Place’ include a new national network of Gigabit libraries to offer superfast internet services to users, and the expansion of the Right to Read Programme and the Right to Read Local Networks.</p>
<p>‘The Library is the Place’ is available to view <a href="https://www.gov.ie/en/policy-information/7468fd-public-libraries/#the-library-is-the-place-information-recreation-inspiration-national-public-library-strategy-2023-2027">here</a></p>
<p>Also announced today was a €550,000 allocation in funding for library supports for marginalised and disadvantaged communities under the 2023 Dormant Accounts Action Plan.</p>
<p>The Department says the funding will support a Digital Equity and Social Inclusion programme to purchase library equipment, the Little Library Programme for incoming Junior Infants pupils, and events and programmes targeted at disadvantaged communities.</p>
<p>&nbsp;</p>', 'A new five-year National Library Strategy was launched today, which plans to place libraries “at the heart of our communities”.', 'https://changingireland.ie/wp-content/uploads/2023/07/library.jpg', '', '[{"slug":"community","title":"Community"}]', '[{"slug":"community","title":"Community"},{"slug":"community-development","title":"community development"},{"slug":"community-libraries","title":"community libraries"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"digital-equity","title":"digital equity"},{"slug":"dormant-accounts-action-plan","title":"Dormant accounts action plan"},{"slug":"dormant-accounts-fund","title":"Dormant Accounts Fund"},{"slug":"funding","title":"funding"},{"slug":"libraries","title":"libraries"},{"slug":"libraries-ireland","title":"libraries ireland"},{"slug":"mobile-library","title":"mobile library"},{"slug":"national-library-strategy","title":"national library strategy"},{"slug":"social-inclusion","title":"social inclusion"}]', '', 253209, 1, '2023-07-17T14:35:07Z', '2023-07-17T14:35:07Z', '2023-07-17T14:35:07Z')
