INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Islands policy provides “a good foundation” – Comhar na nOileán', 'islands-policy-provides-a-good-foundation-comhar-na-noilean', '<p>The ten-year national policy, entitled ‘Our Living Islands’, was launched by Minister for Rural and Community Development, Heather Humphreys in Arranmore Island, Co Donegal on Wednesday.</p>
<p>The document is the first whole-of-Government policy for the islands to be published in 27 years.</p>
<p>Máire Uí Mhaoláin, CEO of Comhar na nOileán, the Local Development Company for the inhabited offshore islands of Ireland, told Changing Ireland: “Comhar na nOileán and many islanders welcome the national islands policy. We feel that it is a good foundation on which much can now be achieved.</p>
<p>“Without going into the detail of the action plan, we especially welcome the formation of an interdepartmental group on which Minister Humphreys will sit as well as representatives from the islands.  This will allow many challenges to be addressed in real time.”</p>
<p><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2023/06/Screenshot_20230607_112819_OneDrive.jpg" alt="" width="739" height="1279" srcset="https://changingireland.ie/wp-content/uploads/2023/06/Screenshot_20230607_112819_OneDrive.jpg 739w, https://changingireland.ie/wp-content/uploads/2023/06/Screenshot_20230607_112819_OneDrive-173x300.jpg 173w, https://changingireland.ie/wp-content/uploads/2023/06/Screenshot_20230607_112819_OneDrive-592x1024.jpg 592w" sizes="(max-width: 739px) 100vw, 739px" /></p>
<p>Ms Uí Mhaoláin added: “We believe that Minister Humphreys and her officers had a job of work to do to engage other departments in accepting that they also have a role to play with regard to the Irish islands. We commend them for that work.</p>
<p>“The policy and action plan is a living document and there will be challenges, but it is a significant development and the islands are now all the better for having a specific policy and action plan than heretofore.”</p>
<p>A scheme to boost the islands’ housing supply through the renovation of derelict and vacant buildings, as well as supports for remote working facilities on every island feature in the policy.</p>
<p>The document also contains a three-year action plan with 80 commitments focusing on improving housing and water infrastructure, access to essential services in health and education, delivering high speed broadband, supporting remote working and further developing outdoor amenities and sustainable tourism.</p>
<p>The policy was developed following an extensive consultation process with island communities and other stakeholders, taking into account their views on the challenges and opportunities associated with living on offshore islands.</p>
<p>Our Living Islands can be downloaded in full <a href="https://www.gov.ie/en/policy-information/a7188-our-living-islands/">here</a></p>
<p>&nbsp;</p>', 'Residents of Ireland’s offshore islands believe that the new national policy for island communities provides a good foundation to help address some of the challenges facing them.', 'https://changingireland.ie/wp-content/uploads/2023/06/347238162_579289044307083_1348797146747931250_n.jpg', '', '[{"slug":"policy-strategy","title":"Policy & Strategy"}]', '[{"slug":"comhar-na-noilean","title":"Comhar na nOileán"},{"slug":"community-development","title":"community development"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"irelands-islands","title":"Ireland''s islands"},{"slug":"islands-policy","title":"islands policy"},{"slug":"local-development-company","title":"local development company"},{"slug":"maire-ui-mhaolain","title":"Máire Uí Mhaoláin"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"offshore-islands","title":"offshore islands"},{"slug":"our-living-islands","title":"Our Living Islands"}]', '', 253146, 1, '2023-06-09T11:37:09Z', '2023-06-09T11:44:41Z', '2023-06-09T11:37:09Z')
