INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Strategic plan launched to build community development among Travellers in Clare', 'strategic-plan-launched-to-build-community-development-among-travellers-in-clare', '<p>This will be pursued through establishing and strengthening local alliances and, most importantly, through building effective Traveller leadership and a strong Traveller voice.</p>
<p>The strategy highlights the conviction that much-needed and urgent change for Travellers in Clare will come about only if Travellers themselves are at the centre of that change.</p>
<p>This strategy will guide the implementation of changes and improvements to the living conditions and life opportunities available to members of the Travelling community throughout County Clare over the next number of years.</p>
<p>Minister O’Brien said: “Community development is all about supporting and empowering communities to face current and future challenges, this is evident in abundance in the plan.”</p>
<p>“I welcome how clear the plan is about the size of the challenge, and the very serious issues facing members of the Traveller community in housing, living conditions, access to education and employment, the lived everyday experience of discrimination and unfortunately – the grave reality of the unacceptable levels of mental health issues affecting the Travelling community.”</p>
<p>“I am confident that you will in time achieve the goals set out in this plan; that is; establishing and strengthening local alliances, building effective Traveller leadership and most importantly giving Travellers in Clare that voice; the voice to help make those important decisions that affect their lives and the lives of their community”</p>
<p>Clare CDP was one of the projects selected for the new Community Development Programme launched in June 2021. This programme helped Clare Traveller CDP to develop community development responses to a range of social and environmental concerns, and facilitate an empowering collaborative approach to building relationships between marginalised groups and mainstream services.</p>
<p>Minister O’Brien concluded: “I’d like to commend Clare Traveller CDP, who are in their second year of the programme, for their hard work and commitment to date. True community development is trusting communities to develop their own solutions and pathways. The evidence is here, you are making a real difference to the lives of the Travelling communities you have supported since the start of this programme.”</p>
<blockquote><p><a href="https://changingireland.ie/funding-for-three-more-projects-granted-under-community-development-pilot-programme/">Funding for three more projects granted under Community Development Programme</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Funding for three more projects granted under Community Development Programme” — Changing Ireland" src="https://changingireland.ie/funding-for-three-more-projects-granted-under-community-development-pilot-programme/embed/#?secret=TLaYjKdkoL#?secret=h4GR28M5Lo" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>
<p>&nbsp;</p>', 'The Clare Traveller Community Development Programme Strategic Plan 2023 – 2026 was launched in Ennis this morning by Minister for Community Development and Charities, Joe O’Brien. Clare Traveller CDP aims to improve living conditions, opportunities and achievement of human rights for Travellers in Clare.', 'https://changingireland.ie/wp-content/uploads/2023/05/FxXoNroWAAkpgcB-1.jpeg', '', '[{"slug":"community","title":"Community"}]', '[{"slug":"clare-traveller-cdp","title":"Clare Traveller CDP"},{"slug":"community-development","title":"community development"},{"slug":"community-development-programme","title":"Community Development Programme"},{"slug":"county-clare","title":"County Clare"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"ennis","title":"Ennis"},{"slug":"ireland","title":"Ireland"},{"slug":"minister-joe-obrien","title":"Minister Joe O''Brien"},{"slug":"travellers","title":"Travellers"},{"slug":"travelling-community","title":"Travelling Community"}]', '', 253095, 1, '2023-05-30T12:37:36Z', '2023-06-02T17:47:12Z', '2023-05-30T12:37:36Z')
