INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Government urged to increase core social welfare rates by €25', 'government-urged-to-increase-core-social-welfare-rates-by-e25', '<p>That’s according to Social Justice Ireland’s<em> </em>policy brief <a href="https://www.socialjustice.ie/system/files/file-uploads/2023-05/2023-05-29%20-%20Budget%202024%20Benchmarking%20and%20Indexation%20Final%20WEB.pdf">‘Social Welfare Rates Budget 2024: The Case for Benchmarking and Indexation’.</a></p>
<p>“Adequate levels of social welfare are essential to addressing poverty. Government must increase core social welfare rates by €25 in the forthcoming Budget. Income adequacy cannot be addressed by one-off measures. Budget 2023 failed to deliver for vulnerable and low-income households as the necessary increase to the minimum social welfare payment was not made. A repetition of this mistake would mean Government yet again fails those on low incomes,” read a statement from the organisation.</p>
<p>Social Justice Ireland also stressed the crucial role of social welfare in reducing poverty, and revealed that without the social welfare system, just over one third of the Irish population (36.7 per cent) would have been living in poverty in 2022.</p>
<p>The statement continued: “Such an underlying poverty rate suggests a deeply unequal distribution of direct income. In 2022, the actual poverty figure of 13.1 per cent reflects the fact that social welfare payments reduced poverty by almost 24 percentage points.  If Government is serious about meeting its own poverty targets and supporting households on the lowest incomes who, through good and bad economic times, struggle to live life on a low income, the core social welfare rates must increase by €25 in the Budget.”</p>
<p>In addition, Social Justice Ireland is calling on the Government to benchmark social welfare rates to 27.5 per cent of average weekly earnings in Budget 2024.</p>
<p>The organisation says this benchmark “is hugely important to improving the living standards of many in Irish society, and to achieving anti-poverty commitments”.</p>
<p>“This benchmark should be used as the starting point in the development of a pathway to index core social welfare rates to the Minimum Essential Budget Standard over time. Achieving this benchmark requires an €25 increase in core social welfare payments,” the statement concluded.</p>', 'Core social welfare rates must increase by €25 in Budget 2024, and the Government must commit to benchmarking social welfare rates to average weekly earnings if it is to have any impact on reducing poverty.', 'https://changingireland.ie/wp-content/uploads/2019/08/money-1005477_1280.jpg', '50 euro notes', '[{"slug":"income-employment","title":"Income & Employment"}]', '[{"slug":"budget-2024","title":"Budget 2024"},{"slug":"community-development","title":"community development"},{"slug":"income","title":"income"},{"slug":"ireland","title":"Ireland"},{"slug":"poverty","title":"Poverty"},{"slug":"social-inclusion","title":"social inclusion"},{"slug":"social-justice-ireland","title":"Social Justice Ireland"},{"slug":"social-welfare","title":"social welfare"}]', '', 253093, 1, '2023-05-30T10:26:48Z', '2023-05-30T10:26:48Z', '2023-05-30T10:26:48Z')
