INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Funding for three more projects granted under Community Development Programme', 'funding-for-three-more-projects-granted-under-community-development-pilot-programme', '<p>The aim of the Community Development Programme (CDP), launched in 2021, is to trial community-led interventions that address poverty, social exclusion and inequality, and promote human rights.</p>
<p>Today’s announcement in Limerick hosts one of the successful projects – a Traveller-led project to enhance integration for members of the Traveller community in Limerick and in wider society generally.</p>
<p>The expansion of the programme builds on the established seven CDP projects in Donegal, Clare, Dublin, Kilkenny, Longford, Wexford and Meath. These projects are providing flexibility to develop community development responses and facilitating and empowering collaborative approaches to building relationships between marginalised groups and main stream services.</p>
<p>Minister O’Brien said: “I am delighted to be here in Limerick today to announce funding for three additional projects under the Community Development Pilot Programme. Three very different projects in three different locations; the Women’s Muslim community in Dublin, the AMACH! LGBTI+ community in Galway and here in Limerick; we will be supporting the Limerick Traveller community.</p>
<figure aria-describedby="caption-attachment-253086"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2023/05/FcDjEa3WIAEdzf8-1024x576.jpeg" alt="" width="1024" height="576" srcset="https://changingireland.ie/wp-content/uploads/2023/05/FcDjEa3WIAEdzf8-1024x576.jpeg 1024w, https://changingireland.ie/wp-content/uploads/2023/05/FcDjEa3WIAEdzf8-300x169.jpeg 300w, https://changingireland.ie/wp-content/uploads/2023/05/FcDjEa3WIAEdzf8-768x432.jpeg 768w, https://changingireland.ie/wp-content/uploads/2023/05/FcDjEa3WIAEdzf8-1536x864.jpeg 1536w, https://changingireland.ie/wp-content/uploads/2023/05/FcDjEa3WIAEdzf8-1080x608.jpeg 1080w, https://changingireland.ie/wp-content/uploads/2023/05/FcDjEa3WIAEdzf8.jpeg 1600w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>&#8211; <em>Members of Amal Women&#8217;s Association, one of the 10 projects to date awarded funding from the 124 that originally applied when the Community Development Programme launched in 2021.<br /></em></figcaption></figure>
<p>“It is vital that the needs and challenges facing those most vulnerable and marginalised in our society are recognised and they are empowered to engage, share their experiences and have their voices heard. This programme provides this opportunity.</p>
<p>“The programme facilitates a community-led approach to addressing significant social challenges. It is important to tailor interventions to the specific context and involves the affected communities in decision making processes. This is what the Community Development Programme is all about.”</p>
<p>The Local Community Development Committees (LCDCs) also play a key role in the programme, providing support and facilitating networking for the projects.</p>
<hr />
<p><strong>The Community Development Programme (CDP)</strong> aims to trial community led interventions that address poverty, social exclusion and inequality and promote human rights.</p>
<p>The programme was launched on March 4 2021 and seven projects were successful. To date, funding of €125,000 has been allocated to each of the seven CDPs for Year 1 and Year 2.</p>
<p>Additional funding is available in 2023 for the expansion of the programme. Following a closed call for applications in 2023, three projects: Amal Women’s Association, AMACH! LGBTI+ Galway and Limerick Traveller Network (LTN)/ Exchange House Ireland (EHI) were invited to apply.</p>
<hr />
<h3>The Projects</h3>
<p><strong>Amal Women&#8217;s Association, Dublin</strong> is a not-for-profit organisation operating in the community and voluntary sector to provide culturally specific services for women and children from Muslim and non-Muslim backgrounds in Ireland. It is an organisation where all women, particularly Muslim women, can access the services they need and fully participate in society, free from the threat of violence, from poverty, racism, discrimination and stigma.</p>
<p><strong>AMACH! LGBTI+, Galway</strong> aims to reflect equally the diversity within the lesbian, gay, bisexual and transgender community by encouraging positive participation from the community. They actively advocate to achieve a solid and safe support structure for the LGBTI+ community in Galway. They also aim to provide awareness, educational and training events and workshops, and endeavour to support and promote a socially inclusive society.</p>
<p><strong>Limerick Traveller Network (LTN)</strong> is an emerging Traveller group which addresses a clear need. Exchange House Ireland (EHI), which is a national organisation, will act as a host for this project.</p>
<p>Limerick Traveller Network is a network of eight Traveller sites and housing areas in Limerick city, representing a total of 114 families. It operates under the principles of community development and aims to strengthen its present grassroots structure to provide a constant flow of participation and information between the community and its representatives.</p>
<p>The network aims to give Travellers in Limerick a voice, build up Travellers&#8217; capacity to advocate and work towards improving accommodation, education, mental health, and discrimination, and to build up working relations with existing structures, services and agencies.</p>
<p><iframe title="Launch of Limerick Travellers Network May 29 2023" width="696" height="392" src="https://www.youtube.com/embed/xnYkPUq_d5g?feature=oembed" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></p>
<blockquote><p><a href="https://changingireland.ie/strategic-plan-launched-to-build-community-development-among-travellers-in-clare/">Strategic plan launched to build community development among Travellers in Clare</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Strategic plan launched to build community development among Travellers in Clare” — Changing Ireland" src="https://changingireland.ie/strategic-plan-launched-to-build-community-development-among-travellers-in-clare/embed/#?secret=UhqFUmRyrs#?secret=nTKSEqXNjD" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>', 'Minister for Community Development and Charities, Joe O’Brien, today (Monday, May 29) announced funding for three additional projects under the Community Development Pilot Programme, and also officially opened the Limerick Traveller Network and Exchange House Ireland HUB.', 'https://changingireland.ie/wp-content/uploads/2023/05/FevVfa7WIAEOd_T.jpeg', '', '[{"slug":"funding","title":"Funding"}]', '[{"slug":"amach-lgbti","title":"AMACH! LGBTI+"},{"slug":"amal-womens-association","title":"Amal Women''s Association"},{"slug":"community-development","title":"community development"},{"slug":"community-development-programme","title":"Community Development Programme"},{"slug":"dublin","title":"Dublin"},{"slug":"galway","title":"Galway"},{"slug":"lgbti-community","title":"LGBTI+ community"},{"slug":"limerick","title":"Limerick"},{"slug":"limerick-traveller-network","title":"Limerick Traveller Network"},{"slug":"local-community-development-committees","title":"local community development committees"},{"slug":"minister-joe-obrien","title":"Minister Joe O''Brien"},{"slug":"travelling-community","title":"Travelling Community"}]', '', 253084, 1, '2023-05-29T19:01:12Z', '2023-06-03T14:34:25Z', '2023-05-29T19:01:12Z')
