INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Speed-dating for not-for-profits seeking board members', 'speed-dating-for-not-for-profits-seeking-board-members', '<p>Boardmatch Ireland is the only Irish charity which specialises in not-for-profit board recruitment and its annual Charity Trustee Speed-Dating event provides an opportunity for both groups and individuals in Dublin and neighbouring counties to meet.</p>
<p>While Boardmatch primarily provides its services online, including board reviews, training, and a free online matching service, this one-day event every autumn allows for direct, face-to-face interaction.</p>
<p>“It allows individuals to meet as many charities as they would like, ask their questions in real-time, and network with other prospective trustees,” said Susan Colgan of Boardmatch.</p>
<p>This year&#8217;s event will be the fourth of its kind.</p>
<p>“During the pandemic, we took a break from hosting this event, however, we came back in 2022 after a three-year hiatus with great success: more than 40 board and committee appointments were made,” said Susan.</p>
<p>“The atmosphere in the room is palpable, and our feedback shows that not only is the event a great way of building connections, but is also really enjoyable,” she added.</p>
<p><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2023/05/HIGH-RES-Matthew-Rose-Nel-MRN-Photography-BoardMatch-Speed-Dating-0498-scaled.jpg" alt="" width="2560" height="1706" srcset="https://changingireland.ie/wp-content/uploads/2023/05/HIGH-RES-Matthew-Rose-Nel-MRN-Photography-BoardMatch-Speed-Dating-0498-scaled.jpg 2560w, https://changingireland.ie/wp-content/uploads/2023/05/HIGH-RES-Matthew-Rose-Nel-MRN-Photography-BoardMatch-Speed-Dating-0498-300x200.jpg 300w, https://changingireland.ie/wp-content/uploads/2023/05/HIGH-RES-Matthew-Rose-Nel-MRN-Photography-BoardMatch-Speed-Dating-0498-1024x683.jpg 1024w, https://changingireland.ie/wp-content/uploads/2023/05/HIGH-RES-Matthew-Rose-Nel-MRN-Photography-BoardMatch-Speed-Dating-0498-768x512.jpg 768w, https://changingireland.ie/wp-content/uploads/2023/05/HIGH-RES-Matthew-Rose-Nel-MRN-Photography-BoardMatch-Speed-Dating-0498-1536x1024.jpg 1536w, https://changingireland.ie/wp-content/uploads/2023/05/HIGH-RES-Matthew-Rose-Nel-MRN-Photography-BoardMatch-Speed-Dating-0498-2048x1365.jpg 2048w, https://changingireland.ie/wp-content/uploads/2023/05/HIGH-RES-Matthew-Rose-Nel-MRN-Photography-BoardMatch-Speed-Dating-0498-1080x720.jpg 1080w" sizes="(max-width: 2560px) 100vw, 2560px" /></p>
<p>Groups wishing to take part pay €100 while individuals pay €20. Groups that book in before the end of June are eligible for an early-bird registration charge of €50.</p>
<p>The organisations taking part will be from Dublin and surrounding counties of Meath, Louth, Kildare and Wicklow. While Boardmatch is considering running this event in other parts of the country, particularly in Munster.</p>
<p>“We have no plans to do so this year, but this could definitely be a possibility,” said Susan.</p>
<p>A dedicated website covers FAQs<strong>:</strong> <a href="https://www.boardmatch-trustee-speed-dating.ie/">https://www.boardmatch-trustee-speed-dating.ie/</a></p>
<p>Boardmatch receives funding through the Scheme to Support National Organisations which is administered by Pobal on behalf of the Department of Rural and Community Development.</p>
<h2>TO BOOK:</h2>
<p>Register as a candidate here: <a href="https://www.boardmatch-trustee-speed-dating.ie/boardmatch-charity-trustee-speed-dating/p/candidate-registration">https://www.boardmatch-trustee-speed-dating.ie/boardmatch-charity-trustee-speed-dating/p/candidate-registration</a></p>
<p>Register as a charity/not-for-profit here: <a href="https://www.boardmatch-trustee-speed-dating.ie/boardmatch-charity-trustee-speed-dating/p/not-for-profit-registration">https://www.boardmatch-trustee-speed-dating.ie/boardmatch-charity-trustee-speed-dating/p/not-for-profit-registration</a></p>
<p>&nbsp;</p>', 'October 4th will see the return of a match-making event with a difference in Dublin city centre. People will not head to the Custom House Quay building on George’s Dock seeking romance, but to become part of something bigger – by joining a not-for-profit group or charitable organisation.', 'https://changingireland.ie/wp-content/uploads/2023/05/HIGH-RES-Matthew-Rose-Nel-MRN-Photography-BoardMatch-Speed-Dating-0394-scaled.jpg', '', '[{"slug":"planning-governance","title":"Planning & Governance"}]', '[{"slug":"boardmatch","title":"Boardmatch"},{"slug":"chq","title":"CHQ"},{"slug":"speed-dating","title":"speed-dating"},{"slug":"trustees","title":"trustees"}]', '', 253088, 1, '2023-05-29T17:29:39Z', '2023-05-29T17:29:39Z', '2023-05-29T17:29:39Z')
