INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('A further €438,000 in funding granted to community and voluntary organisations', 'a-further-e438000-in-funding-granted-to-community-and-voluntary-organisations', '<p>Today’s funding announcement brings the total number of organisations supported under the initiative to 846, with over €1.35 million now disbursed.</p>
<p>Further tranches of funding are to be announced and paid shortly.</p>
<p>The successful applicants include:</p>
<p>Fingal Community and Recreations Services CLG, Co Dublin: €28,274</p>
<p>St Bernard’s Children’s Services, Co Tipperary: €8,549</p>
<p>Muff Sheltered Housing Association, Co Donegal: €13,751</p>
<p>Drogheda Women&#8217;s and Children&#8217;s Refuge Centre, Co Louth: €6,120</p>
<p>Teach Bhride Holistic Education Centre, Co Carlow (pictured):  €6,492</p>
<p>Minister for Rural and Community Development, Heather Humphreys commented: “Community and voluntary organisations deliver vital services in our communities. Targeted supports such as the CVESS mean they can get on with the important work they do, this kind of funding gives them space to concentrate on what people really need from them.”</p>
<p>She confirmed that further tranches will follow: “Pobal continues to assess applications in batches as we engage with organisations to seek clarifications as needed and to give every organisation the best opportunity to be successful in their application.</p>
<p>The government is also urging householders and businesses to ensure that they are availing of the supports that are in place. For more information visit <a href="http://www.gov.ie/reduceyouruse">www.gov.ie/reduceyouruse</a></p>
<p><a href="https://www.gov.ie/en/collection/08468-community-voluntary-energy-support-scheme-cvess/">The full list of successful applicants is available here</a></p>', 'The latest tranche of funding under the Community and Voluntary Energy Support Scheme (CVESS) has provided an additional €438,000 to 166 organisations nationwide. The payments provide a one-off contribution towards increased energy bills for 2022, and will issue to the organisations immediately.', 'https://changingireland.ie/wp-content/uploads/2023/05/12794485_973028099441243_8434020927349481621_n.jpg', '', '[{"slug":"funding","title":"Funding"}]', '[{"slug":"carlow","title":"Carlow"},{"slug":"community-and-voluntary-energy-support-scheme-cvess","title":"Community and Voluntary Energy Support Scheme (CVESS)"},{"slug":"community-and-voluntary-organisations","title":"community and voluntary organisations"},{"slug":"community-and-voluntary-sector","title":"Community and Voluntary sector"},{"slug":"cost-of-living-crisis","title":"cost-of-living crisis"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"donegal","title":"Donegal"},{"slug":"drogheda-womens-and-childrens-refuge-centre","title":"Drogheda Women''s and Children''s Refuge Centre"},{"slug":"dublin","title":"Dublin"},{"slug":"energy-crisis","title":"energy crisis"},{"slug":"fingal-community-and-recreations-services-clg","title":"Fingal Community and Recreations Services CLG"},{"slug":"funding","title":"funding"},{"slug":"louth","title":"Louth"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"minister-joe-obrien","title":"Minister Joe O''Brien"},{"slug":"muff-sheltered-housing-association","title":"Muff Sheltered Housing Association"},{"slug":"st-bernards-childrens-services","title":"St Bernard''s Childrens Services"},{"slug":"teach-bhride-holistic-education-centre","title":"Teach Bhride Holistic Education Centre"},{"slug":"tipperary","title":"Tipperary"}]', '', 253080, 1, '2023-05-26T11:36:13Z', '2023-05-26T11:48:59Z', '2023-05-26T11:36:13Z')
