INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Public consultation begins on Ireland’s first National Philanthropy Policy', 'public-consultation-begins-on-irelands-first-national-philanthropy-policy', '<p>The proposed policy is intended to deepen understanding and knowledge, create an enabling environment and accelerate engagement with philanthropy in Ireland for social good.</p>
<p>A statement from the Department of Rural and Community Development said: “Non-profit organisations play an important role in Ireland’s social and economic life and receive part of their funding from philanthropic sources. The range of non-profit organisations which benefit from philanthropy is diverse, ranging from small community groups like sports clubs to large national organisations.</p>
<p>“The aim of this policy is to set out clear objectives, and specific actions to enable philanthropy to grow and thrive in Ireland for social good. The philanthropy policy will also support knowledge and capacity development of the sector. It will also identify the supports required for it to thrive and maximise its potential.”</p>
<p>Minister O’Brien said that his Department is now widening the consultation process on the policy and encouraged interested parties to take the opportunity to have their say on a policy “that aims to create an understanding of the philanthropy sector and underpin its importance to civic society”.</p>
<p>More information on the National Philanthropy Policy Public Consultation is available <a href="https://www.gov.ie/en/consultation/7a227-national-philanthropy-policy-public-consultation/">here</a> .</p>', 'A proposed policy that intends to encourage and grow philanthropy in Ireland was announced this week by Minister for Community Development and Charities, Joe O’Brien. Ireland’s First National Philanthropy Policy is being developed by the Government in collaboration with key stakeholders. The public consultation phase of the policy was launched on May 23 at The Wheel’s Annual Summit.', 'https://changingireland.ie/wp-content/uploads/2023/05/SUMMIT-PIC-1.jpg', '', '[{"slug":"funding","title":"Funding"}]', '[{"slug":"charities","title":"charities"},{"slug":"community-development","title":"community development"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"funding","title":"funding"},{"slug":"irelands-first-national-philanthropy-policy","title":"Ireland''s First National Philanthropy POlicy"},{"slug":"minister-joe-obrien","title":"Minister Joe O''Brien"},{"slug":"non-profit-organisations","title":"non-profit organisations"},{"slug":"philanthropy","title":"philanthropy"},{"slug":"public-consultation","title":"public consultation"},{"slug":"the-wheel","title":"The Wheel"}]', '', 253073, 1, '2023-05-25T09:48:05Z', '2023-05-25T09:48:05Z', '2023-05-25T09:48:05Z')
