INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Week-long event gives communities the chance to get to know local gardaí', 'week-long-event-gives-communities-the-chance-to-get-to-know-local-gardai', '<p>Each day of National Community Engagement Week is themed, covering different aspects of rural living including: community safety; road and pedestrian safety; burglary, theft and heritage crime; personal safety and wellbeing; and farmer and rural safety.</p>
<p>IFA Deputy President and co-chair of the National Rural Safety Forum, Brian Rushe, said: &#8220;It is vitally important that communities works together to serve the best interests of people at risk and the National Rural Community Engagement Week is the perfect platform for this.</p>
<p>&#8220;IFA are very pleased to be working with An Garda Síochána and members of the National Rural Safety Forum on this great initiative and are urging all communities to come out to support this programme.&#8221;</p>
<p>The events aim to empower communities to acquire advice and knowledge that promotes and maintains personal safety and security, as well as promoting best safety and security practices.</p>
<p>Chaired by An Garda Síochána and the IFA, and supported by the Department of Justice, the Department of Rural and Community Development, Muintir na Tíre, AgriKids, and a range of State agencies and representative groups, the Forum’s focus on rural safety is laid out in the National Rural Safety Plan 2022-2024.</p>
<p>The purpose of the Forum is to develop a nationwide network for the distribution of crime prevention advice, increase engagement within communities and prevent and reduce opportunities for crime.</p>
<p>The series of events, organised by the Rural Safety Forum, is an opportunity for communities to get to know their local gardaí and community representatives. All are welcome, and details of events can be found here: <a href="https://t.co/MAiXqIthsB"><span aria-hidden="true">https://</span>loom.ly/EHBk-UU</a></p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>', 'National Community Engagement Week kicks off today, with events taking place in communities across Ireland to give people the opportunity to get to know their local gardaí and representatives. Previously run over the course of just one day, this expanded week-long series facilitated by the National Rural Safety Forum runs from May 22 to 26 this year.', 'https://changingireland.ie/wp-content/uploads/2023/05/national-community-engagement-week.png', '', '[{"slug":"community","title":"Community"}]', '[{"slug":"agrikids","title":"AgriKids"},{"slug":"an-garda-siochana","title":"An Garda Siochána"},{"slug":"community-development","title":"community development"},{"slug":"department-of-justice","title":"Department of Justice"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"gardai","title":"Gardaí"},{"slug":"irish-farmers-association-ifa","title":"Irish Farmers Association IFA"},{"slug":"muintir-na-tire","title":"Muintir na Tíre"},{"slug":"national-community-engagement-week","title":"National Community Engagement Week"},{"slug":"national-rural-safety-forum","title":"National Rural Safety Forum"},{"slug":"national-rural-safety-plan","title":"National Rural Safety Plan"}]', '', 253064, 1, '2023-05-22T10:39:49Z', '2023-05-22T10:39:49Z', '2023-05-22T10:39:49Z')
